from produire import produire,paras,steps,table
from medicaments import antalgie
parts=[
('La {cervicalgie commune non spécifique} est une douleur cervicale sans cause spécifique identifiée après évaluation adaptée. Elle peut s’accompagner de raideur et de douleurs musculaires. Le diagnostic reste réévaluable si le tableau change.',paras('Le terme ne signifie ni douleur imaginaire ni absence de retentissement. Une anomalie dégénérative peut être présente à l’imagerie sans expliquer la plainte.', 'Un torticolis décrit une position douloureuse du cou ; il ne suffit pas, à lui seul, à conclure à une forme commune. Une radiculopathie déficitaire, une myélopathie, une infection ou un traumatisme instable sortent de cette catégorie.')),
('Le {contexte est fréquent et souvent multifactoriel}. Travail, sommeil, activité et facteurs psychosociaux peuvent influencer la gêne. Les récidives sont possibles, sans que toute douleur persistante traduise une lésion grave.',paras('Le retentissement sur conduite, habillage, concentration et sommeil guide les objectifs. Les chiffres étrangers de prévalence ne sont pas présentés comme des mesures suisses.', 'Rechercher peur du mouvement et inquiétude liée à l’imagerie. Ces éléments peuvent entretenir l’incapacité, mais ne dispensent jamais de rechercher les signes d’alarme.')),
('Le {mécanisme associe douleur et fonction}. Muscles, articulations et tissus cervicaux peuvent contribuer aux symptômes. La relation entre anomalies radiologiques et intensité douloureuse est imparfaite.',paras('Une contraction protectrice limite parfois les mouvements ; l’immobilisation prolongée peut renforcer appréhension et perte de capacité. L’explication du mécanisme aide à réintroduire des mouvements tolérables.', 'L’évolution chronique peut comporter des modifications du traitement de la douleur par le système nerveux. Cela justifie une approche globale et active, sans attribuer automatiquement toute plainte au stress.')),
('Les {alarmes doivent être exclues avant le conseil de bouger}. Fièvre, traumatisme à risque, céphalée brutale ou déficit neurologique changent la conduite. Une douleur progressive inhabituelle exige une nouvelle évaluation.',paras('Rechercher trouble de marche, mains maladroites, troubles sphinctériens, cancer connu, immunosuppression et symptômes généraux. Sur un rachis ankylosé, un traumatisme mineur peut provoquer une fracture.', 'La mobilité active proposée dans la forme commune ne s’applique pas à une suspicion d’instabilité ou de dissection.')),
('L’{anamnèse décrit le fonctionnement quotidien}. Préciser début, déclencheurs, irradiation, sommeil et activités limitées. Rechercher les attentes et les traitements déjà essayés.',paras('Noter doses cumulées d’antalgiques, effets indésirables, arrêts de travail et évolution. Évaluer si la douleur s’améliore, reste stable ou progresse.', 'Une sensation de fourmillement nécessite une localisation et un examen neurologique ; elle ne doit être ni ignorée ni automatiquement qualifiée de compression radiculaire.')),
('L’{examen vérifie la cohérence du tableau}. Observer posture et mobilité active, palper prudemment et examiner les épaules. Compléter par un examen neurologique adapté.',paras('Dans une forme commune, douleur et limitation peuvent être présentes, sans déficit radiculaire ou signe médullaire objectif. Tester la marche et la dextérité si l’histoire l’évoque.', 'Aucune palpation isolée ne démontre une vertèbre déplacée. Éviter les gestes forcés destinés à confirmer une hypothèse mécanique avant exclusion d’une cause grave.')),
('L’{approche syndromique distingue douleur axiale et atteinte nerveuse}. Une irradiation vers l’épaule peut rester non radiculaire. Une faiblesse, des réflexes anormaux ou une marche perturbée demandent une autre analyse.',table(['Profil','Interprétation'],[['Douleur locale liée à certaines activités, sans alarme.','Compatible avec forme commune après évaluation.'],['Douleur du bras avec déficit concordant.','Rechercher radiculopathie.'],['Maladresse des mains et troubles de marche.','Rechercher myélopathie.'],['Raideur fébrile ou céphalée brutale.','Explorer une urgence infectieuse ou vasculaire.']])) ,
('Le {diagnostic positif est clinique et évolutif}. Il repose sur une présentation compatible et l’absence d’argument pour une cause spécifique. Il ne nécessite pas de démontrer une arthrose.',paras('L’amélioration progressive sous prise en charge active soutient la stratégie, sans constituer une preuve étiologique. L’apparition d’alarme impose de reprendre l’évaluation.', 'Ne pas multiplier les étiquettes anatomiques à partir d’images incidentes. Expliquer clairement ce qui a été examiné et les raisons du suivi.')),
('Les {examens ne sont pas systématiques}. Une cervicalgie commune récente sans alarme ne demande généralement ni radiographie ni biologie. Une persistance limitante malgré prise en charge conduit à réévaluer.',paras('Les recommandations retiennent une réévaluation de l’indication d’imagerie après quatre à six semaines en cas de persistance ou progression. Ce repère ne signifie pas attendre en présence d’une alarme.', 'La modalité dépend alors de la question clinique. La HAS et la recommandation allemande diffèrent sur la place de la radiographie conventionnelle ; retenir surtout l’indication ciblée et éviter une imagerie automatique sans conséquence attendue.')),
('L’{algorithme accompagne une récupération active}. Il associe tri, explication, objectifs réalistes et contrôle de l’évolution. Une aggravation clinique modifie immédiatement le plan.',steps('Vérifier absence de cause spécifique et de signe d’alarme.', 'Expliquer le diagnostic de travail et définir une activité prioritaire à récupérer.', 'Proposer mouvements progressifs, exercices et adaptation temporaire des activités.', 'Discuter un traitement symptomatique bref selon risques.', 'Réévaluer fonction et signes nouveaux ; discuter bilan ciblé si évolution défavorable.')),
('La {prise en charge suisse privilégie l’activité adaptée}. Éducation, exercices et reprise progressive sont centraux. Un médicament peut aider brièvement sans devenir le traitement unique.',paras('Chaleur locale prudente et physiothérapie peuvent accompagner la reprise. Éviter immobilisation et collier de routine. Les soins passifs seuls ne remplacent pas la participation active.', '@@MEDICAMENTS@@', 'La recommandation allemande de 2025 ne recommande pas opioïdes ni myorelaxants pour la cervicalgie non spécifique. L’effet des anti-inflammatoires est modeste et leur usage prolongé expose à des risques. Le paracétamol présenté comme option symptomatique n’a pas ici une efficacité spécifique garantie.', 'Une manipulation avec impulsion ne constitue pas une étape obligatoire. Discuter indication, alternatives et risques ; aucune manipulation devant suspicion vasculaire, neurologique ou d’instabilité.')),
('Le {suivi vérifie surtout la fonction}. Ajuster les activités et les exercices à la tolérance. Donner les signes de reconsultation urgente et une échéance de réévaluation.',paras('Urgence devant nouveau déficit, trouble de marche, céphalée brutale ou fièvre avec altération générale. Réévaluation anticipée devant aggravation persistante ou effet indésirable médicamenteux.', 'Encourager une activité régulière et variée, sans promettre qu’une posture parfaite ou un dispositif empêche toute récidive. Les adaptations de travail doivent être réalistes et centrées sur les limitations observées.')),
('Le {message principal} associe sécurité et maintien de la fonction. La forme commune est un diagnostic clinique de travail. Une image d’arthrose ne remplace ni l’examen ni le suivi.',paras('Le patient doit savoir quoi faire, quel progrès attendre et quand reconsulter. Une prise en charge active n’autorise pas à ignorer une évolution inhabituelle.'))]
quiz=[('Non spécifique signifie-t-il imaginaire ?','Non.'),('Une radiographie d’arthrose suffit-elle au diagnostic ?','Non, la concordance clinique est essentielle.'),('Quel symptôme de la main évoque une atteinte médullaire ?','Une maladresse nouvelle, surtout avec trouble de marche.'),('Le repos prolongé est-il le traitement habituel ?','Non, favoriser une activité adaptée.'),('Le collier est-il systématique ?','Non dans la forme commune.'),('Faut-il une IRM d’emblée sans alarme ?','Généralement non.'),('Quatre à six semaines autorisent-elles à attendre devant un déficit ?','Non.'),('Les facteurs psychosociaux remplacent-ils le bilan organique ?','Non.'),('Une irradiation scapulaire est-elle forcément radiculaire ?','Non.'),('Quel est le rôle des exercices ?','Aider à récupérer mouvement et fonction, progressivement.'),('Les anti-inflammatoires sont-ils utiles indéfiniment ?','Non, bénéfice bref et risques à évaluer.'),('Les opioïdes sont-ils recommandés en routine ici ?','Non.'),('Une manipulation forcée est-elle obligatoire ?','Non, et elle est à éviter devant suspicion de cause grave.'),('Quel résultat suivre au-delà de la douleur ?','La fonction dans les activités quotidiennes et l’absence de signes nouveaux.')]
produire(1,parts,quiz,(1,2,7,9,11,12),antalgie)
